function Profile() {
  const user = JSON.parse(localStorage.getItem("user"));

  return (
    <div style={{ padding: "30px" }}>
      <h1>Profile</h1>

      <h3>Name: {user?.name}</h3>
      <h3>Email: {user?.email}</h3>

      <h2 style={{ marginTop: "30px" }}>Orders</h2>

      <p>No orders yet</p>
    </div>
  );
}

export default Profile;
